import sys
MOD = 998244353

def main():
    d = list(map(int, sys.stdin.buffer.read().split()))
    if not d:
        return
    n, m = d[0], d[1]
    q = d[2:]
    exact = [[0] * n for _ in range(n)]
    for i in range(0, 3*m, 3):
        l, r, x = q[i]-1, q[i+1]-1, q[i+2]-1
        exact[l][r] |= 1 << x

    bad = [[0] * n for _ in range(n)]
    for a in range(n-1, -1, -1):
        row = bad[a]
        below = bad[a+1] if a+1 < n else None
        er = exact[a]
        for b in range(a, n):
            v = er[b]
            if below is not None:
                v |= below[b]
            if b > a:
                v |= row[b-1]
            row[b] = v

    fac = [1] * n
    for i in range(1, n):
        fac[i] = fac[i-1] * i % MOD
    ifac = [1] * n
    ifac[-1] = pow(fac[-1], MOD-2, MOD)
    for i in range(n-1, 0, -1):
        ifac[i-1] = ifac[i] * i % MOD
    choose = [[0] * n for _ in range(n)]
    for z in range(n):
        f = fac[z]
        for j in range(z+1):
            choose[z][j] = f * ifac[j] % MOD * ifac[z-j] % MOD

    dp = [[0] * n for _ in range(n)]
    for a in range(n):
        dp[a][a] = 0 if ((bad[a][a] >> a) & 1) else 1
    for length in range(2, n+1):
        for a in range(n-length+1):
            b = a + length - 1
            forbidden = bad[a][b]
            total = 0
            for k in range(a, b+1):
                if not ((forbidden >> k) & 1):
                    left = dp[a][k-1] if k > a else 1
                    right = dp[k+1][b] if k < b else 1
                    total += choose[length-1][k-a] * left * right
            dp[a][b] = total % MOD
    print(dp[0][n-1])

if __name__ == '__main__':
    main()

