def main():
    z = list(map(int, sys.stdin.buffer.read().split()))
    if not z:
        return
    n, m = z[0], z[1]
    a = [x - 1 for x in z[2:]]
    rev = [[] for _ in range(n)]
    indeg = [0] * n
    for i, p in enumerate(a):
        rev[p].append(i)
        indeg[p] += 1
    q = [i for i in range(n) if indeg[i] == 0]
    for v in q:
        p = a[v]
        indeg[p] -= 1
        if indeg[p] == 0:
            q.append(p)
    iscycle = [x != 0 for x in indeg]
    seen = [False] * n
    cycles = []
    for i in range(n):
        if iscycle[i] and not seen[i]:
            c = []
            v = i
            while not seen[v]:
                seen[v] = True
                c.append(v)
                v = a[v]
            cycles.append(c)

    answer = 1
    for cycle in cycles:
        combined = [1] * (m + 1)
        for root in cycle:
            order = []
            stack = [u for u in rev[root] if not iscycle[u]]
            while stack:
                v = stack.pop()
                order.append(v)
                for u in rev[v]:
                    if not iscycle[u]:
                        stack.append(u)
            dp = {}
            for v in reversed(order):
                f = [1] * (m + 1)
                for u in rev[v]:
                    if not iscycle[u]:
                        g = dp[u]
                        s = 0
                        for k in range(1, m + 1):
                            s += g[k]
                            if s >= MOD:
                                s -= MOD
                            f[k] = f[k] * s % MOD
                        del dp[u]
                dp[v] = f
            for u in rev[root]:
                if not iscycle[u]:
                    g = dp[u]
                    s = 0
                    for k in range(1, m + 1):
                        s += g[k]
                        if s >= MOD:
                            s -= MOD
                        combined[k] = combined[k] * s % MOD
                    del dp[u]
        ways = sum(combined[1:]) % MOD
        answer = answer * ways % MOD
    print(answer)

