import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    a = data[1:]
    factors = {}
    for i, x in enumerate(a):
        d = 2
        y = x
        while d * d <= y:
            if y % d == 0:
                c = 0
                while y % d == 0:
                    y //= d
                    c += 1
                factors.setdefault(d, [0] * (n - 1))[i] = c
            d += 1
        if y > 1:
            factors.setdefault(y, [0] * (n - 1))[i] = 1

    answer = 1
    for p, exponents in factors.items():
        hmax = sum(exponents)
        limit = 2 * hmax
        powers = [1] * (limit + 1)
        for h in range(1, limit + 1):
            powers[h] = powers[h - 1] * p % MOD

        total = [0] * (limit + 1)
        no_zero = [0] * (limit + 1)
        for h in range(hmax + 1):
            total[h] = powers[h]
            if h:
                no_zero[h] = powers[h]

        for e in exponents:
            new_total = [0] * (limit + 1)
            new_no_zero = [0] * (limit + 1)
            for h, v in enumerate(total):
                if v:
                    d = h + e
                    new_total[d] = (new_total[d] + v * powers[d]) % MOD
                    if e and h >= e:
                        d = h - e
                        new_total[d] = (new_total[d] + v * powers[d]) % MOD
            for h, v in enumerate(no_zero):
                if v:
                    d = h + e
                    new_no_zero[d] = (new_no_zero[d] + v * powers[d]) % MOD
                    if e and h >= e and h - e > 0:
                        d = h - e
                        new_no_zero[d] = (new_no_zero[d] + v * powers[d]) % MOD
            total, no_zero = new_total, new_no_zero

        answer = answer * (sum(total) - sum(no_zero)) % MOD

    print(answer)

