import sys

MOD = 998244353
MAXA = 100000

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]

    phi = list(range(MAXA + 1))
    for p in range(2, MAXA + 1):
        if phi[p] == p:
            for v in range(p, MAXA + 1, p):
                phi[v] -= phi[v] // p

    divisors = [[] for _ in range(MAXA + 1)]
    for d in range(1, MAXA + 1):
        for v in range(d, MAXA + 1, d):
            divisors[v].append(d)

    weighted = [0] * (MAXA + 1)
    answer = 0
    weight = 1
    output = []

    for x in a:
        total = 0
        for d in divisors[x]:
            total += phi[d] * weighted[d]
        answer = (2 * answer + total) % MOD
        output.append(str(answer))

        for d in divisors[x]:
            z = weighted[d] + weight
