from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        import heapq

        ending = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, i))

        heap = []
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in ending[right]:
                heapq.heappush(heap, (-left, idx))

            if not heap:
                total += right
                continue

            largest = -heap[0][0]
            if len(heap) == 1:
                second = 0
            elif len(heap) == 2:
                second = -heap[1][0]
            else:
                second = -max(heap[1][0], heap[2][0])

            total += right - largest
            if largest > second:
                gains[heap[0][1]] += largest - second

        return total + max(gains)

