import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it)); m = int(next(it)); q = int(next(it))

    edges = []
    for _ in range(m):
        a = int(next(it)) - 1
        b = int(next(it)) - 1
        c = int(next(it))
        edges.append((a, b, c))

    queries = []
    closed = [False] * m
    for _ in range(q):
        typ = int(next(it))
        if typ == 1:
            e = int(next(it)) - 1
            queries.append((1, e))
            closed[e] = True
        else:
            x = int(next(it)) - 1
            y = int(next(it)) - 1
            queries.append((2, x, y))

    INF = 10**30
    dist = [[INF] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for i, (a, b, c) in enumerate(edges):
        if not closed[i] and c < dist[a][b]:
            dist[a][b] = c
            dist[b][a] = c

    for k in range(n):
        row_k = dist[k]
        for i in range(n):
            row_i = dist[i]
            dik = row_i[k]
            if dik == INF:
                continue
            for j in range(n):
                v = dik + row_k[j]
                if v < row_i[j]:
                    row_i[j] = v

    answers = []
    for query in reversed(queries):
        if query[0] == 2:
            x, y = query[1], query[2]
            value = dist[x][y]
            answers.append(str(value if value < INF else -1))
        else:
            a, b, c = edges[query[1]]
            row_a = dist[a][:]
            row_b = dist[b][:]
            col_a = [row[a] for row in dist]
            col_b = [row[b] for row in dist]
            for i in range(n):
                row_i = dist[i]
                via_a = col_a[i] + c
                via_b = col_b[i] + c
                for j in range(n):
                    value = via_a + row_b[j]
                    other = via_b + row_a[j]
                    if other < value:
                        value = other
                    if value < row_i[j]:
                        row_i[j] = value

    sys.stdout.write("\n".join(reversed(answers)))

if __name__ == "__main__":
    main()

