    seen = [0] * (n + 1)
    cnt = 0
    for i, x in enumerate(a, 1):
        prev[i] = seen[x]
        seen[x] = i
        if prev[i] == 0:
            cnt += 1
        pref[i] = cnt

    suf = [0] * (n + 1)
    seen = [0] * (n + 1)
    cnt = 0
    for i in range(n, 0, -1):
        if not seen[a[i - 1]]:
            seen[a[i - 1]] = 1
            cnt += 1
        suf[i] = cnt

    size = 1
    while size < n:
        size <<= 1
    neg = -10**9
    tree = [neg] * (2 * size)
    lazy = [0] * (2 * size)
    for i in range(1, n):
        tree[size + i] = pref[i]
    for k in range(size - 1, 0, -1):
        tree[k] = max(tree[2*k], tree[2*k+1])

