        def rec(k, lo, hi):
            if right <= lo or hi <= left:
                return
            if left <= lo and hi <= right:
                tree[k] += 1
                lazy[k] += 1
                return
            mid = (lo + hi) // 2
            rec(2*k, lo, mid)
            rec(2*k+1, mid, hi)
            tree[k] = lazy[k] + max(tree[2*k], tree[2*k+1])
