class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        m = len(s)
        C = [[0]*(m+1) for _ in range(m+1)]
        C[0][0] = 1
        for i in range(1, m+1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        good = [False]*(m+1)
        for t in range(1, m+1):
            x, steps = t, 0
            while x != 1 and steps <= k:
                x = x.bit_count()
                steps += 1
            good[t] = (x == 1 and steps <= k-1)
        ans = 0
        pref = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = m-i-1
                for t in range(1, m+1):
                    if good[t]:
                        need = t-pref
                        if 0 <= need <= rem:
                            ans = (ans + C[rem][need]) % MOD
                pref += 1
        return ans

