import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, x = data[0], data[1]
    vals = data[2:]
    u = vals[::2]
    d = vals[1::2]

    def feasible(h):
        lo = max(0, h - d[0])
        hi = min(u[0], h)
        if lo > hi:
            return False
        for i in range(1, n):
            need_lo = max(0, h - d[i])
            need_hi = min(u[i], h)
            lo = max(need_lo, lo - x)
            hi = min(need_hi, hi + x)
            if lo > hi:
                return False
        return True

    low = 0
    high = min(a + b for a, b in zip(u, d)) + 1
    while high - low > 1:
        mid = (low + high) // 2
        if feasible(mid):
            low = mid
        else:
            high = mid

    print(sum(u) + sum(d) - n * low)

if __name__ == "__main__":
    main()

