import sys, heapq

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    H = next(it); W = next(it); X = next(it)
    P = next(it) - 1; Q = next(it) - 1
    a = [next(it) for _ in range(H * W)]

    start = P * W + Q
    current = a[start]
    seen = bytearray(H * W)
    seen[start] = 1
    heap = []

    def add(v):
        if not seen[v]:
            seen[v] = 1
            heapq.heappush(heap, (a[v], v))

    if P > 0: add(start - W)
    if P + 1 < H: add(start + W)
    if Q > 0: add(start - 1)
    if Q + 1 < W: add(start + 1)

    while heap and heap[0][0] * X < current:
        value, v = heapq.heappop(heap)
        current += value
        r, c = divmod(v, W)
        if r > 0: add(v - W)
        if r + 1 < H: add(v + W)
        if c > 0: add(v - 1)
        if c + 1 < W: add(v + 1)

    print(current)

if __name__ == '__main__':
    main()

