import sys,bisect

def main():
    v=list(map(int,sys.stdin.buffer.read().split()))
    if not v:return
    N,M,X=v[:3]; k=3
    A=[];B=[];S=[];T=[]
    for _ in range(M):
        A.append(v[k]);B.append(v[k+1]);S.append(v[k+2]);T.append(v[k+3]);k+=4
    vals=[[] for _ in range(N+1)]
    for i in range(M): vals[B[i]].append(T[i])
    bits=[]
    for c in range(N+1):
        vals[c]=sorted(set(vals[c])); bits.append([-(10**30)]*(len(vals[c])+1))
    def update(c,x,val):
        p=bisect.bisect_left(vals[c],x)+1; b=bits[c]
        while p<len(b):
            if val>b[p]: b[p]=val
            p+=p&-p
    def query(c,x):
        p=bisect.bisect_right(vals[c],x); b=bits[c]; r=-(10**30)
        while p:
            if b[p]>r:r=b[p]
            p-=p&-p
        return r
    dp=[t for t in T]; dp[0]=X+T[0]
    for i in sorted(range(M),key=lambda q:T[q]):
        if i!=0:
            q=query(A[i],S[i])
            if q>-(10**20): dp[i]=max(dp[i],q+T[i]-S[i])
        update(B[i],T[i],dp[i])
    out=[]
    for i in range(1,M): out.append(str(max(0,dp[i]-T[i])))
    print(' '.join(out))
