import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    at = 2
    for _ in range(m):
        u, v = data[at] - 1, data[at + 1] - 1
        at += 2
        rows[u] |= 1 << v
        rows[v] |= 1 << u

    # Put the adjacency matrix into reduced row echelon form over GF(2).
    a = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        found = -1
        for i in range(rank, n):
            if (a[i] >> col) & 1:
                found = i
                break
        if found < 0:
            continue
        a[rank], a[found] = a[found], a[rank]
        for i in range(n):
            if i != rank and ((a[i] >> col) & 1):
                a[i] ^= a[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]
    basis = []
    for f in free:
        x = 1 << f
        for i, p in enumerate(pivots):
            if (a[i] >> f) & 1:
                x |= 1 << p
        basis.append(x)

    values = [0] * n
    for bit, vec in enumerate(basis):
        for v in range(n):
            if (vec >> v) & 1:
                values[v] |= 1 << bit

    if any(x == 0 for x in values):
        print("No")
    else:
