class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2
        weights = []
        for i in range(half):
            if n % 2 and i == n // 2:
                weights.append(pow(10, i, k))
            else:
                weights.append((pow(10, i, k) + pow(10, n - 1 - i, k)) % k)

        # suffix[i][r] says whether positions i onward can contribute
        # residue r modulo k.
        suffix = [None] * (half + 1)
        terminal = bytearray(k)
        terminal[0] = 1
        suffix[half] = terminal

        for i in range(half - 1, -1, -1):
            possible = bytearray(k)
            first_digit = 1 if i == 0 else 0
            w = weights[i]
            following = suffix[i + 1]
            for digit in range(first_digit, 10):
                shift = digit * w
                for residue in range(k):
                    if following[(residue - shift) % k]:
                        possible[residue] = 1
            suffix[i] = possible

        digits = []
        needed = 0
        for i, w in enumerate(weights):
            first_digit = 1 if i == 0 else 0
            for digit in range(9, first_digit - 1, -1):
                remaining = (needed - digit * w) % k
                if suffix[i + 1][remaining]:
                    digits.append(str(digit))
                    needed = remaining
                    break

        left = ''.join(digits)
        if n % 2:
            return left + left[:-1][::-1]
        return left + left[::-1]

