from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        seg_sum = [0] * (4 * n + 5)
        lazy = [None] * (4 * n + 5)

        def apply(p, left, right, value):
            seg_sum[p] = value * (right - left + 1) - (pref[right + 1] - pref[left])
            lazy[p] = value

        def push(p, left, right):
            value = lazy[p]
            if value is not None and left < right:
                mid = (left + right) // 2
                apply(p * 2, left, mid, value)
                apply(p * 2 + 1, mid + 1, right, value)
                lazy[p] = None

        def assign(p, left, right, ql, qr, value):
            if ql <= left and right <= qr:
                apply(p, left, right, value)
                return
            push(p, left, right)
            mid = (left + right) // 2
            if ql <= mid:
                assign(p * 2, left, mid, ql, qr, value)
            if qr > mid:
                assign(p * 2 + 1, mid + 1, right, ql, qr, value)
            seg_sum[p] = seg_sum[p * 2] + seg_sum[p * 2 + 1]

        # Find the first position at or after ql whose cumulative cost exceeds k.
        def first_over(p, left, right, ql, accumulated):
            if right < ql:
                return -1, accumulated
            if ql <= left and accumulated + seg_sum[p] <= k:
                return -1, accumulated + seg_sum[p]
            if left == right:
                return left, accumulated
            push(p, left, right)
            mid = (left + right) // 2
            found, accumulated = first_over(p * 2, left, mid, ql, accumulated)
            if found != -1:
                return found, accumulated
            return first_over(p * 2 + 1, mid + 1, right, ql, accumulated)

        stack = []
        answer = 0
        for i in range(n - 1, -1, -1):
            while stack and nums[stack[-1]] <= nums[i]:
                stack.pop()
            next_greater = stack[-1] if stack else n

            # For a window beginning at i, nums[i] is the running maximum
            # through next_greater - 1.
            assign(1, 0, n - 1, i, next_greater - 1, nums[i])
            stack.append(i)

            bad, _ = first_over(1, 0, n - 1, i, 0)
            if bad == -1:
                answer += n - i
            else:
                answer += bad - i

        return answer

