class Solution:
    def maximumSubarrayXor(self, nums, queries):
        n = len(nums)
        best = [array('I', [0]) * n for _ in range(n)]
        score = [0] * n

        for right in range(n):
            score[right] = nums[right]
            best[right][right] = nums[right]
            for left in range(right - 1, -1, -1):
                score[left] ^= score[left + 1]
                value = score[left]
                other = best[left + 1][right]
                if other > value:
                    value = other
                other = best[left][right - 1]
                if other > value:
                    value = other
                best[left][right] = value

        return [best[left][right] for left, right in queries]

