class Solution:
    def makeStringGood(self, s: str) -> int:
        a=[0]*26
        for c in s: a[ord(c)-97]+=1
        n=len(s); cand={1,*a}
        # Breakpoints are also produced by balancing groups of frequencies.
        for i in range(26):
            for j in range(i+1,26):
                cand.add((a[i]+a[j])//2); cand.add((a[i]+a[j]+1)//2)
        INF=10**18; ans=n
        for k in cand:
            if k<=0: continue
            dp=[INF]*(k+1); dp[0]=0
            for x in a:
                su=[INF]*(k+2)
                for i in range(k,-1,-1): su[i]=min(su[i+1],dp[i]+i)
                nd=[INF]*(k+1)
                for b in (0,k):
                    th=b-x
                    if th>0:
                        for i in range(min(k,th-1)+1): nd[0]=min(nd[0],dp[i]-i+th)
                    for y in range(k+1):
                        lo=max(0,y+th)
                        if lo<=k: nd[y]=min(nd[y],su[lo]+x-b)
                dp=nd
            ans=min(ans,min(dp[i]+i for i in range(k+1)))
