    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        parent = [-1] * n
        parent[0] = -2
        order = [0]
        for u in order:
            for v, w in graph[u]:
                if parent[v] == -1:
                    parent[v] = u
                    order.append(v)

        free = [0] * n
        with_parent_edge = [0] * n

        for u in reversed(order):
            base = 0
            gains = []
            for v, w in graph[u]:
                if parent[v] == u:
                    base += free[v]
                    gains.append(w + with_parent_edge[v] - free[v])
            gains.sort(reverse=True)
            free[u] = base + sum(x for x in gains[:k] if x > 0)
            with_parent_edge[u] = base + sum(x for x in gains[:max(0, k - 1)] if x > 0)

        return free[0]

