import sys
from functools import lru_cache

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m, l = data[:3]
    values = data[3:]
    total = n + m + l
    all_mask = (1 << total) - 1
    takahashi = (1 << n) - 1
    aoki = ((1 << m) - 1) << n

    sys.setrecursionlimit(1000000)

    @lru_cache(None)
    def winning(t_hand, a_hand, turn):
        hand = t_hand if turn == 0 else a_hand
        table = all_mask ^ t_hand ^ a_hand
        choices = hand
        while choices:
            played = choices & -choices
            choices -= played
            p = played.bit_length() - 1

            # Play without taking a card from the table.
            if turn == 0:
                nt, na = t_hand ^ played, a_hand
            else:
                nt, na = t_hand, a_hand ^ played
            if not winning(nt, na, 1 - turn):
                return True

            # Try each card smaller than the played card.
            candidates = table
            while candidates:
                taken = candidates & -candidates
                candidates -= taken
                q = taken.bit_length() - 1
                if values[q] < values[p]:
                    if turn == 0:
                        nt, na = (t_hand ^ played) | taken, a_hand
                    else:
                        nt, na = t_hand, (a_hand ^ played) | taken
                    if not winning(nt, na, 1 - turn):
                        return True
        return False

    print("Takahashi" if winning(takahashi, aoki, 0) else "Aoki")

if __name__ == "__main__":
    solve()

