MOD = 998244353

def solve(H, W, rows):
    # First, the parity required for the horizontal and vertical cycles.
    for s in rows:
        if s.count('A') & 1:
            return 0
    colpar = [0] * W
    for s in rows:
        for j, c in enumerate(s):
            colpar[j] ^= (c == 'A')
    if any(colpar):
        return 0

    n = H + W
    parent = list(range(n))
    xr = [0] * n

    def find(x):
        if parent[x] != x:
            q = parent[x]
            parent[x] = find(q)
            xr[x] ^= xr[q]
        return parent[x]

    def join(a, b, v):
        ra = find(a); va = xr[a]
        rb = find(b); vb = xr[b]
        if ra == rb:
            return (va ^ vb) == v
        parent[ra] = rb
        xr[ra] = va ^ vb ^ v
        return True

    # hp is the prefix parity of A's in the current row; cp[j] is
    # the corresponding prefix in column j.
    cp = [0] * W
    for i, s in enumerate(rows):
        hp = 0
        for j, c in enumerate(s):
            if c == 'B':
                # The two seed edge variables must have opposite values
                # (with the accumulated prefix parities included).
                if not join(i, H + j, 1 ^ hp ^ cp[j]):
                    return 0
            if c == 'A':
                hp ^= 1
                cp[j] ^= 1

    roots = {find(i) for i in range(n)}
    return pow(2, len(roots), MOD)

