class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        first, middle, last = p.split('*')
        n = len(s)

        def occurrences(pattern):
            m = len(pattern)
            if m == 0:
                return None
            prefix = [0] * m
            j = 0
            for i in range(1, m):
                while j and pattern[i] != pattern[j]:
                    j = prefix[j - 1]
                if pattern[i] == pattern[j]:
                    j += 1
                prefix[i] = j

            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != pattern[j]:
                    j = prefix[j - 1]
                if ch == pattern[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = prefix[j - 1]
            return result

        def next_occurrence(pattern):
            if not pattern:
                return list(range(n + 1))
            present = occurrences(pattern)
            nxt = [-1] * (n + 1)
            for pos in present:
                nxt[pos] = pos
            nearest = -1
            for i in range(n, -1, -1):
                if nxt[i] != -1:
                    nearest = nxt[i]
                nxt[i] = nearest
            return nxt

        lf, lm, ll = len(first), len(middle), len(last)
        starts = occurrences(first) if first else range(n + 1)
        next_middle = next_occurrence(middle)
        next_last = next_occurrence(last)

        answer = n + 1
        for start in starts:
            after_first = start + lf
            if after_first > n:
                continue
            middle_start = next_middle[after_first]
            if middle_start < 0:
                continue
            after_middle = middle_start + lm
            if after_middle > n:
                continue
            last_start = next_last[after_middle]
            if last_start < 0:
                continue
            answer = min(answer, last_start + ll - start)

        return -1 if answer == n + 1 else answer

