import sys

def solve(A, B):
    p = [i for i, c in enumerate(A) if c == '1']
    q = [i for i, c in enumerate(B) if c == '1']
    if len(p) < len(q):
        return -1

    def feasible(d):
        # Select distinct, order-preserving source pieces for the targets.
        t = 0
        prev = -1
        for x in q:
            while t < len(p) and p[t] <= prev:
                t += 1
            while t < len(p) and p[t] < x - d:
                t += 1
            if t == len(p) or p[t] > x + d:
                return False
            prev = t
            t += 1

        # Every remaining piece must also be placeable at some target.
        j = 0
        for z in p:
            while j + 1 < len(q) and q[j + 1] <= z:
                j += 1
            if min(abs(z - q[j]),
                   abs(z - q[min(j + 1, len(q) - 1)])) > d:
                return False
        return True

    lo, hi = -1, len(A)
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid
    return hi

