class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = 10**30
        min_prefix = [INF] * k
        min_prefix[0] = 0
        prefix = 0
        best = -INF

        for end, value in enumerate(nums, 1):
            prefix += value
            residue = end % k
            if min_prefix[residue] != INF:
                best = max(best, prefix - min_prefix[residue])
            if prefix < min_prefix[residue]:
                min_prefix[residue] = prefix

        return best

