from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        # dp[i] is a bitset: bit s is set if index i can have received
        # total decrement s using the queries seen so far.
        dp = [1] * len(nums)
        masks = [(1 << (x + 1)) - 1 for x in nums]

        if all(x == 0 for x in nums):
            return 0

        for count, (left, right, value) in enumerate(queries, 1):
            for i in range(left, right + 1):
                dp[i] = (dp[i] | (dp[i] << value)) & masks[i]
            if all((dp[i] >> nums[i]) & 1 for i in range(len(nums))):
                return count
        return -1

