    def minOperations(self, n: int, m: int) -> int:
        length = len(str(n))
        limit = 10 ** length
        prime = bytearray(b'\1') * limit
        prime[0] = prime[1] = 0
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                prime[p * p:limit:p] = b'\0' * ((limit - 1 - p * p) // p + 1)
        if prime[n] or prime[m]:
            return -1

        inf = 10 ** 30
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]
        while heap:
            cost, value = heapq.heappop(heap)
            if cost != dist[value]:
                continue
            if value == m:
                return cost
            text = f'{value:0{length}d}'
            for pos, ch in enumerate(text):
                digit = ord(ch) - 48
                if digit < 9:
                    candidate = int(text[:pos] + str(digit + 1) + text[pos + 1:])
                    if not prime[candidate] and cost + candidate < dist[candidate]:
                        dist[candidate] = cost + candidate
                        heapq.heappush(heap, (dist[candidate], candidate))
                if digit > 0 and not (length > 1 and pos == 0 and digit == 1):
                    candidate = int(text[:pos] + str(digit - 1) + text[pos + 1:])
                    if not prime[candidate] and cost + candidate < dist[candidate]:
                        dist[candidate] = cost + candidate
                        heapq.heappush(heap, (dist[candidate], candidate))
        return -1

