from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0

        def make_z(a):
            m = len(a)
            z = [0] * m
            left = right = 0
            for k in range(1, m):
                if k < right:
                    z[k] = min(right - k, z[k - left])
                while k + z[k] < m and a[z[k]] == a[k + z[k]]:
                    z[k] += 1
                if k + z[k] > right:
                    left, right = k, k + z[k]
            return z

        # z0[i] is the LCP length of nums and nums[i:].
        z0 = make_z(nums)
        answer = 0

        for first_end in range(1, n - 1):
            remaining = n - first_end
            z = make_z(nums[first_end:])

            # For the second condition, the second part must fit in the
            # third part, so its length d is at most remaining // 2.
            limit = remaining // 2

            # If nums1 is a prefix of nums2, every d >= first_end works.
            if z0[first_end] >= first_end:
                answer += remaining - first_end
                # These lengths have already been counted; only test d below it.
                limit = min(limit, first_end - 1)

            for d in range(1, limit + 1):
                # z[d] compares nums[first_end:] with nums[first_end+d:].
                if z[d] >= d:
                    answer += 1

        return answer

