def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    k = int(data[0])
    s, t = data[1], data[2]
    if s == t:
        print('Yes')
        return
    if abs(len(s) - len(t)) > 1:
        print('No')
        return
    if len(s) == len(t):
        mismatches = sum(a != b for a, b in zip(s, t))
        print('Yes' if mismatches <= 1 else 'No')
