class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        base = s.count('1')
        runs = []
        i = 0
        n = len(s)
        while i < n:
            j = i + 1
            while j < n and s[j] == s[i]:
                j += 1
            runs.append((s[i], j - i))
            i = j

        m = len(runs)
        eligible = sorted(
            (runs[p][1], p)
            for p in range(1, m - 1)
            if runs[p][0] == '1'
        )
        best_gain = 0

        # Turn off a 1-run and then turn on the zero-run formed around it.
        for p in range(1, m - 1):
            if runs[p][0] == '1':
                best_gain = max(best_gain, runs[p - 1][1] + runs[p + 1][1])

        # Alternatively, turn on a different zero-run after turning off
        # the cheapest eligible, non-adjacent 1-run.
        for q, (ch, zero_len) in enumerate(runs):
            if ch != '0':
                continue
            for one_len, p in eligible:
                if p != q - 1 and p != q + 1:
                    best_gain = max(best_gain, zero_len - one_len)
                    break

        return base + best_gain

