    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        answer = 0
        n = len(word)

        for left in range(n):
            present = set()
            consonants = 0
            for right in range(left, n):
                ch = word[right]
                if ch in vowels:
                    present.add(ch)
                else:
                    consonants += 1

                if consonants > k:
                    break
                if consonants == k and len(present) == 5:
                    answer += 1

        return answer

