from typing import List
class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        s = {(x,y) for x,y in points}
        xs = sorted({x for x,y in points})
        ys = sorted({y for x,y in points})
        ans = -1
        for i in range(len(xs)):
            for j in range(i+1,len(xs)):
                x1,x2=xs[i],xs[j]
                for k in range(len(ys)):
                    for l in range(k+1,len(ys)):
                        y1,y2=ys[k],ys[l]
                        if not ((x1,y1) in s and (x1,y2) in s and (x2,y1) in s and (x2,y2) in s):
                            continue
                        ok=True
                        for x,y in points:
                            if x1<=x<=x2 and y1<=y<=y2 and (x,y) not in ((x1,y1),(x1,y2),(x2,y1),(x2,y2)):
                                ok=False; break
                        if ok: ans=max(ans,(x2-x1)*(y2-y1))
        return ans

