from typing import List
class Solution:
    def countArrays(self, original: List[int], bounds: List[List[int]]) -> int:
        lo = -10**30
        hi = 10**30
        for x, (u, v) in zip(original, bounds):
            lo = max(lo, u - x)
            hi = min(hi, v - x)
        return max(0, hi - lo + 1)

